const FRASES_FIM=['Hoje tava gostosinho, né?','Mais um pro placar.','Esse foi do capeta, hein.','Corpo cansado, cabeça leve.','Amanhã tem mais. Bora!','Que ódio, mas tá feito.'];
const FRASES_PR=['Estagnado é a vó.','Tá ficando forte, hein!','O quadro que lute.'];
function recordesDe(s){ const out=[]; if(!s) return out;
  if(s.kind==='corrida'){ if(s.local==='box'||!s.distKm) return out; const ant=allSessions().filter(x=>x.kind==='corrida'&&x.local!=='box'&&x.id!==s.id&&x.date<=s.date);
    if(!ant.length) return out; const maxKm=Math.max(...ant.map(x=>x.distKm||0)); if(s.distKm>maxKm) out.push({t:'Corrida mais longa',v:fmtNum(s.distKm,2)+' km'});
    const ps=ant.filter(x=>x.pace&&(x.distKm||0)>=1).map(x=>x.pace); if(s.pace&&s.distKm>=1&&ps.length&&s.pace<Math.min(...ps)) out.push({t:'Melhor ritmo',v:pace(s.pace)+'/km'}); return out; }
  const idx=exerciseIndex(); const visto=new Set(); const itens=(s.blocks||[]).flatMap(b=>b.items||[]);
  for(const i of itens){ if(i.loadKg==null||visto.has(i.name)) continue; visto.add(i.name); const e=idx[i.name]; if(!e) continue;
    const ant=e.sessions.filter(r=>r.id!==s.id&&r.max!=null&&r.date<=s.date); if(!ant.length) continue;
    const prev=Math.max(...ant.map(r=>r.max)); const mx=Math.max(...itens.filter(x=>x.name===i.name&&x.loadKg!=null).map(x=>x.loadKg));
    if(mx>prev) out.push({t:i.name,v:fmtNum(mx)+' kg',mais:'+'+fmtNum(mx-prev)+' kg'}); }
  return out.slice(0,3); }
