  const medRows=MED.filter(([k])=>ev.some(e=>e.medidas&&e.medidas[k]!=null)).map(([k,l])=>`<tr><td>${l}</td>${ev.map(e=>`<td>${e.medidas&&e.medidas[k]!=null?fmtNum(e.medidas[k],1):'–'}</td>`).join('')}<td>${(()=>{const d=(z.medidas||{})[k]-(a.medidas||{})[k];return isNaN(d)?'–':`<span class="delta ${d<0?'good':d>0?'bad':''}" style="margin:0">${d>0?'+':''}${d} cm</span>`})()}</td></tr>`).join('');
