    F.forEach(([a,b,n,c])=>ds.push({type:'line',label:n,data:[{x:x0,y:Math.min(b,hi)},{x:x1,y:Math.min(b,hi)}],borderWidth:0,pointRadius:0,fill:'-1',backgroundColor:css(c)+'26'}));
