  const ds=(e,c,dash)=>({label:fmtD(e.date),data:AX.map(x=>val(e,x)),borderColor:css(c),backgroundColor:css(c)+'22',pointBackgroundColor:css(c),borderWidth:2,borderDash:dash||[],raw:AX.map(([k,,u])=>e[k]!=null?fmtNum(e[k],1)+(u?' '+u:''):'–')});
  const grid=css('--line'),tick=css('--muted');
