document.addEventListener('keydown',e=>{ if(e.key!=='n'&&e.key!=='N') return; if(e.ctrlKey||e.metaKey||e.altKey) return; const t=e.target; if(t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return; if(document.querySelector('dialog[open]')||document.body.classList.contains('signed-out')) return; const b=document.getElementById('btnReg'); if(b){ e.preventDefault(); b.click(); } });
